le=&quot;Les halfelins&quot;&gt;Halfelin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Le personnage poss&#232;de toute une s&#233;ries d’objets communs&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Combattant-Prudent.html&quot; title=&quot;Combattant prudent&quot;&gt;Combattant prudent&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Halfelin.html&quot; title=&quot;Les halfelins&quot;&gt;Halfelin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Augmente le bonus &#224; la CA du combat sur la d&#233;fensive et de la d&#233;fense totale&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Coup-D&#233;sesp&#233;r&#233;.html&quot; title=&quot;Coup d&#233;sesp&#233;r&#233;&quot;&gt;Coup d&#233;sesp&#233;r&#233;&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Combattant-Prudent.html&quot; title=&quot;Combattant prudent&quot;&gt;Combattant prudent&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;BBA&lt;/a&gt; +1, &lt;a class=&quot;pagelink&quot; href=&quot;Halfelin.html&quot; title=&quot;Les halfelins&quot;&gt;halfelin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;+4 aux jets de confirmation critique en se battant sur la d&#233;fensive, effectue une attaque en d&#233;fense totale 1 fois par jour&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Frappe-Surprenante.html&quot; title=&quot;Frappe surprenante&quot;&gt;Frappe surprenante&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Combattant-Prudent.html&quot; title=&quot;Combattant prudent&quot;&gt;Combattant prudent&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Coup-D&#233;sesp&#233;r&#233;.html&quot; title=&